"""Clients and client entities (glossary). TASK-008 design §1."""

from __future__ import annotations

from datetime import date, datetime
from decimal import Decimal
from uuid import UUID

from sqlalchemy import FetchedValue
from sqlalchemy.orm import Mapped, mapped_column

from abacus.kernel.db import Base


class Client(Base):
    __tablename__ = "clients"

    id: Mapped[UUID] = mapped_column(primary_key=True)
    tenant_id: Mapped[UUID]
    name: Mapped[str]
    created_at: Mapped[datetime]
    # SPEC-025: generated by the database (`organisations.normalise` mirrors it).
    normalised_name: Mapped[str] = mapped_column(server_default=FetchedValue())
    # F-03-T25 (DEC-62): the client record. `is_attest_client` is derived (DEC-128).
    kind: Mapped[str | None] = mapped_column(server_default=FetchedValue())
    status: Mapped[str] = mapped_column(server_default=FetchedValue())
    primary_office_id: Mapped[UUID | None] = mapped_column(server_default=FetchedValue())
    relationship_partner_id: Mapped[UUID | None] = mapped_column(server_default=FetchedValue())
    risk_tier: Mapped[str | None] = mapped_column(server_default=FetchedValue())
    is_attest_client: Mapped[bool] = mapped_column(server_default=FetchedValue())
    portal_status: Mapped[str] = mapped_column(server_default=FetchedValue())
    practice_mgmt_ref: Mapped[str | None] = mapped_column(server_default=FetchedValue())
    descriptor: Mapped[str | None] = mapped_column(server_default=FetchedValue())  # P-07-T07
    # P-07-T09 (0110): bumped by the database on every change; a PATCH names the one it read.
    version: Mapped[int] = mapped_column(server_default=FetchedValue())


class ClientEntity(Base):
    __tablename__ = "client_entities"

    id: Mapped[UUID] = mapped_column(primary_key=True)
    tenant_id: Mapped[UUID]
    client_id: Mapped[UUID]
    name: Mapped[str]
    created_at: Mapped[datetime]
    normalised_name: Mapped[str] = mapped_column(server_default=FetchedValue())
    # F-03-T25: entity attributes. No TIN column: taxpayer IDs arrive sealed (P-12).
    entity_type: Mapped[str | None] = mapped_column(server_default=FetchedValue())
    fye_month_day: Mapped[str | None] = mapped_column(server_default=FetchedValue())
    state_of_formation: Mapped[str | None] = mapped_column(server_default=FetchedValue())
    plan_number: Mapped[str | None] = mapped_column(server_default=FetchedValue())
    date_of_death: Mapped[date | None] = mapped_column(server_default=FetchedValue())
    grantor_status: Mapped[bool | None] = mapped_column(server_default=FetchedValue())
    # P-07-T07 (0103): what any payload may show of a sealed TIN. The envelope and fingerprint
    # are not mapped here; only P-07-T10's sealing reads or writes them.
    tin_last4: Mapped[str | None] = mapped_column(server_default=FetchedValue())
    tin_kind: Mapped[str | None] = mapped_column(server_default=FetchedValue())
    tin_status: Mapped[str] = mapped_column(server_default=FetchedValue())


class Office(Base):
    """An office of the firm (DEC-30): a filter on lists and dashboards, never an access
    boundary (Q-21)."""

    __tablename__ = "offices"

    id: Mapped[UUID] = mapped_column(primary_key=True, server_default=FetchedValue())
    tenant_id: Mapped[UUID]
    name: Mapped[str]
    time_zone: Mapped[str] = mapped_column(server_default=FetchedValue())
    created_at: Mapped[datetime] = mapped_column(server_default=FetchedValue())
    # G-01-T08 (0150): ADM-03a's office facts. None of them is an access boundary (DEC-30).
    code: Mapped[str] = mapped_column(server_default=FetchedValue())
    is_hq: Mapped[bool] = mapped_column(server_default=FetchedValue())
    address_line1: Mapped[str | None]
    address_line2: Mapped[str | None]
    city: Mapped[str | None]
    region_code: Mapped[str | None]
    postal_code: Mapped[str | None]
    lead_user_id: Mapped[UUID | None]
    default_reviewer_pool_team_id: Mapped[UUID | None]
    version: Mapped[int] = mapped_column(server_default=FetchedValue())


class Team(Base):
    __tablename__ = "teams"

    id: Mapped[UUID] = mapped_column(primary_key=True, server_default=FetchedValue())
    tenant_id: Mapped[UUID]
    office_id: Mapped[UUID | None]
    name: Mapped[str]
    created_at: Mapped[datetime] = mapped_column(server_default=FetchedValue())
    # G-01-T08 (0150): a team or group's kind; a service-line team names its line.
    kind: Mapped[str] = mapped_column(server_default=FetchedValue())
    service_line: Mapped[str | None]
    lead_user_id: Mapped[UUID | None]
    version: Mapped[int] = mapped_column(server_default=FetchedValue())


class TeamRoster(Base):
    """One change to a team's roster (the glossary's code name for engagement staff is
    engagement_member, DEC-14, so a team keeps a roster). Insert-only (0150): a removal is a new
    row with `removed_at`; the roster is each person's latest row per team without one."""

    __tablename__ = "team_rosters"

    id: Mapped[UUID] = mapped_column(primary_key=True, server_default=FetchedValue())
    seq: Mapped[int] = mapped_column(server_default=FetchedValue())
    tenant_id: Mapped[UUID]
    team_id: Mapped[UUID]
    user_id: Mapped[UUID]
    added_at: Mapped[datetime] = mapped_column(server_default=FetchedValue())
    removed_at: Mapped[datetime | None]


class Contact(Base):
    """A client's person or third party (F-03-T25; DEC-63); email unique per client."""

    __tablename__ = "contacts"

    id: Mapped[UUID] = mapped_column(primary_key=True)
    tenant_id: Mapped[UUID]
    client_id: Mapped[UUID]
    display_name: Mapped[str]
    email: Mapped[str | None]
    phone: Mapped[str | None]
    title: Mapped[str | None]
    organisation_name: Mapped[str | None]
    contact_kind: Mapped[str]
    normalised_name: Mapped[str] = mapped_column(server_default=FetchedValue())  # 0103
    user_id: Mapped[UUID | None] = mapped_column(server_default=FetchedValue())
    portal_state: Mapped[str] = mapped_column(server_default=FetchedValue())
    party_kind: Mapped[str] = mapped_column(server_default=FetchedValue())  # 0146 (P-07-T25)
    version: Mapped[int] = mapped_column(server_default=FetchedValue())  # 0146
    created_at: Mapped[datetime] = mapped_column(server_default=FetchedValue())


class EntityRelationship(Base):
    """How two of the firm's entities relate (P-07-T07); ended by `effective_to`, never deleted."""

    __tablename__ = "entity_relationships"

    id: Mapped[UUID] = mapped_column(primary_key=True, server_default=FetchedValue())
    tenant_id: Mapped[UUID]
    from_entity_id: Mapped[UUID]
    to_entity_id: Mapped[UUID]
    kind: Mapped[str]
    percent: Mapped[Decimal | None]
    effective_from: Mapped[date]
    effective_to: Mapped[date | None]
    created_by: Mapped[UUID]
    created_at: Mapped[datetime] = mapped_column(server_default=FetchedValue())
